import React, { useState } from 'react';

const Navbar = () => {
  const [isNavOpen, setIsNavOpen] = useState(false);

  const toggleNav = () => {
    setIsNavOpen(!isNavOpen);
  };

  return (
    <nav style={styles.navbar}>
      <div style={styles.logo}>Logo</div>
      <div style={styles.hamburger} onClick={toggleNav}>
        <div style={styles.line}>1</div>
        <div style={styles.line}>2</div>
        <div style={styles.line}>3</div>
      </div>
      <ul style={{ ...styles.navItems, ...(!isNavOpen && styles.hidden) }}>
        <li style={styles.navItem}>Home</li>
        <li style={styles.navItem}>About</li>
        <li style={styles.navItem}>Services</li>
        <li style={styles.navItem}>Contact</li>
      </ul>
    </nav>
  );
};

const styles = {
  navbar: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: '1rem',
    backgroundColor: '#333',
    color: '#fff',
  },
  logo: {
    fontWeight: 'bold',
    fontSize: '1.5rem',
  },
  hamburger: {
    display: 'flex',
    flexDirection: 'column',
    cursor: 'pointer',
    div: {
      width: '25px',
      height: '3px',
      margin: '4px',
      backgroundColor: '#fff',
    },
  },
  navItems: {
    display: 'flex',
    listStyle: 'none',
  },
  navItem: {
    margin: '0 10px',
    cursor: 'pointer',
  },
  hidden: {
    display: 'none',
  },
};

export default Navbar;
